CREATE OR REPLACE VIEW public.v_department AS
SELECT
    d.department_id,
    d.department_name,
    d.department_code,
    d.manager_email,
    d.company_id,
    d.log,
    d.deleted_at,
    c.company_shortname,
    c.company_fullname,
    CONCAT(
        c.company_shortname,
        ' -(',
        COALESCE(d.department_code, ''),
        ')- ',
        d.department_name
    ) AS department_label
FROM public.department d
LEFT JOIN public.my_company c
    ON c.my_company_id = d.company_id;

CREATE OR REPLACE VIEW public.v_department_select AS
SELECT * FROM public.v_department;

