--
-- created table finance
--
CREATE TABLE  public.finance (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    account_code VARCHAR(50) NOT NULL,
    account_type VARCHAR(100),
    account_name VARCHAR(255) NOT NULL,
    description TEXT,
    example TEXT
);



--
-- created view finance
--
CREATE OR REPLACE VIEW public.v_finance AS
SELECT
    f.id,
    f.account_code,
    f.account_type,
    f.account_name,
    f.description,
    f.example,

    CONCAT(
        '(',
        COALESCE(a.account_name, ''),
        ' | ',
        COALESCE(a.currency, ''),
        ') | ',
        COALESCE(f.account_type, ''),
        ' | ',
        COALESCE(f.account_name, ''),
        ' | ',
        COALESCE(f.example, '')
    ) AS finance_label

FROM public.finance AS f
LEFT JOIN public.account AS a
    ON a.account_id = f.account_code;




