--
-- Data for Name: service; Type: TABLE DATA; Schema: public; Owner: crc_user
--


--
--data for name :account_code,account_type,account_name,description,example
--

BEGIN;

    account_code,
    account_type,
    account_name,
    description,
    example
)
VALUES
    ('621', 'Chi phí', 'Chi phí nguyên vật liệu trực tiếp', 'Giá trị nguyên vật liệu, linh kiện và vật tư được sử dụng trực tiếp để thực hiện một dự án, sản xuất hoặc hoàn thiện sản phẩm, giải pháp cho khách hàng.', 'Dây mạng, cáp quang, đầu nối, patch cord, module quang, vật tư điện và linh kiện tiêu hao sử dụng trực tiếp cho dự án triển khai hạ tầng CNTT.'),
    ('622', 'Chi phí', 'Chi phí nhân công trực tiếp', 'Tiền lương, phụ cấp và các chi phí liên quan đến nhân sự trực tiếp thực hiện dự án, triển khai hoặc cung cấp dịch vụ cho khách hàng.', 'Chi phí kỹ sư trực tiếp lắp đặt máy chủ, cấu hình hệ thống, migration dữ liệu, kiểm thử và nghiệm thu dự án.'),
    ('623', 'Chi phí', 'Chi phí sử dụng máy thi công', 'Chi phí phát sinh từ việc sử dụng máy móc, thiết bị chuyên dụng phục vụ thi công, lắp đặt hoặc triển khai hệ thống.', 'Chi phí sử dụng xe nâng, máy khoan, máy hàn cáp quang, máy phát điện hoặc thiết bị nâng để lắp đặt tủ rack và máy chủ.'),
    ('6231', 'Chi phí', 'Chi phí nhân công vận hành máy', 'Tiền lương và các khoản liên quan của nhân sự trực tiếp vận hành máy móc, thiết bị thi công.', 'Chi phí nhân sự vận hành xe nâng hoặc thiết bị nâng trong quá trình đưa máy chủ, UPS và tủ rack vào trung tâm dữ liệu.'),
    ('6232', 'Chi phí', 'Chi phí vật liệu cho máy thi công', 'Nhiên liệu, vật tư và nguyên liệu tiêu hao trong quá trình vận hành máy móc thi công.', 'Dầu diesel cho máy phát điện, dầu bôi trơn, pin hoặc vật tư thay thế cho thiết bị nâng và thiết bị thi công.'),
    ('6233', 'Chi phí', 'Chi phí công cụ, dụng cụ cho máy thi công', 'Chi phí công cụ và dụng cụ sử dụng cùng với máy móc, thiết bị thi công.', 'Mũi khoan, lưỡi cắt, cáp điện, phụ kiện nối hoặc dụng cụ sử dụng với thiết bị lắp đặt hệ thống.'),
    ('6234', 'Chi phí', 'Chi phí khấu hao máy thi công', 'Khấu hao của máy móc, thiết bị chuyên dụng sử dụng trong hoạt động thi công hoặc triển khai.', 'Khấu hao máy hàn cáp quang, máy đo tín hiệu, máy đo cáp mạng hoặc thiết bị nâng thuộc sở hữu công ty.'),
    ('6237', 'Chi phí', 'Chi phí dịch vụ thuê ngoài cho máy thi công', 'Chi phí thuê ngoài liên quan đến máy móc và thiết bị phục vụ thi công.', 'Thuê xe nâng, thuê máy phát điện, thuê thiết bị đo kiểm hoặc thuê đơn vị vận hành thiết bị chuyên dụng.'),
    ('6238', 'Chi phí', 'Chi phí máy thi công khác', 'Các chi phí liên quan đến máy thi công nhưng chưa được phân loại vào các nhóm trên.', 'Chi phí vận chuyển thiết bị thi công, phí kiểm định hoặc phí cấp phép đưa thiết bị chuyên dụng vào địa điểm khách hàng.'),
    ('627', 'Chi phí', 'Chi phí sản xuất chung', 'Các chi phí gián tiếp phục vụ hoạt động cấu hình, tích hợp, kiểm thử, chuẩn bị thiết bị hoặc cung cấp dịch vụ kỹ thuật.', 'Chi phí quản lý phòng lab, điện sử dụng để test thiết bị, khấu hao hệ thống lab và chi phí giám sát kỹ thuật.'),
    ('6271', 'Chi phí', 'Chi phí nhân viên sản xuất', 'Tiền lương và các khoản liên quan của nhân sự gián tiếp phục vụ hoạt động kỹ thuật, tích hợp hoặc triển khai.', 'Lương trưởng nhóm kỹ thuật, quản lý phòng lab hoặc kỹ sư hỗ trợ chung cho nhiều dự án.'),
    ('6272', 'Chi phí', 'Chi phí vật liệu sản xuất', 'Vật tư sử dụng gián tiếp cho hoạt động tích hợp, cấu hình, kiểm thử hoặc chuẩn bị thiết bị.', 'Dây cáp dùng chung, keo tản nhiệt, vật tư vệ sinh thiết bị, đầu nối và linh kiện nhỏ sử dụng trong phòng lab.'),
    ('6273', 'Chi phí', 'Chi phí công cụ, dụng cụ sản xuất', 'Công cụ, dụng cụ được sử dụng trong bộ phận kỹ thuật hoặc khu vực tích hợp hệ thống.', 'Bộ dụng cụ kỹ thuật, máy test cáp, thiết bị đo mạng, dụng cụ chống tĩnh điện và thiết bị bảo hộ.'),
    ('6274', 'Chi phí', 'Chi phí khấu hao tài sản cố định sản xuất', 'Khấu hao tài sản cố định được sử dụng cho hoạt động kỹ thuật, cấu hình và kiểm thử.', 'Khấu hao máy chủ lab, hệ thống lưu trữ, switch mạng, tủ rack và thiết bị kiểm thử.'),
    ('6275', 'Chi phí', 'Thuế, phí và lệ phí sản xuất', 'Thuế, phí và lệ phí liên quan trực tiếp đến khu vực kỹ thuật, sản xuất hoặc tích hợp hệ thống.', 'Phí kiểm định an toàn điện, phí chứng nhận thiết bị hoặc phí cấp phép vận hành khu vực kỹ thuật.'),
    ('6277', 'Chi phí', 'Chi phí dịch vụ sản xuất thuê ngoài', 'Chi phí mua dịch vụ bên ngoài phục vụ hoạt động kỹ thuật, tích hợp, kiểm thử hoặc triển khai.', 'Chi phí thuê data center, thuê chuyên gia, thuê đối tác cấu hình hệ thống hoặc thuê dịch vụ kiểm thử bảo mật.'),
    ('6278', 'Chi phí', 'Chi phí sản xuất chung khác', 'Các chi phí gián tiếp khác phục vụ hoạt động kỹ thuật hoặc tích hợp hệ thống.', 'Chi phí vệ sinh phòng lab, kiểm tra an toàn, đóng gói thử nghiệm hoặc xử lý linh kiện hư hỏng nhỏ.'),
    ('632', 'Chi phí', 'Giá vốn hàng bán', 'Giá vốn của hàng hóa, thiết bị, phần mềm hoặc dịch vụ đã được cung cấp và ghi nhận doanh thu trong kỳ.', 'Giá mua máy chủ, thiết bị lưu trữ, switch, firewall, linh kiện, giấy phép phần mềm hoặc chi phí thuê nhà thầu trực tiếp để cung cấp dịch vụ cho khách hàng.'),
    ('635', 'Chi phí', 'Chi phí tài chính', 'Chi phí phát sinh từ hoạt động vay vốn, ngoại tệ, đầu tư và các hoạt động tài chính khác.', 'Lãi vay dùng để nhập thiết bị, lỗ chênh lệch tỷ giá khi thanh toán nhà cung cấp nước ngoài hoặc lỗ từ khoản đầu tư tài chính.'),
    ('641', 'Chi phí', 'Chi phí bán hàng', 'Chi phí phát sinh để tiếp thị, bán hàng, giao hàng và hỗ trợ hoạt động kinh doanh.', 'Lương nhân viên kinh doanh, chi phí demo giải pháp, quảng cáo, hội thảo khách hàng và chi phí giao thiết bị.'),
    ('6411', 'Chi phí', 'Chi phí nhân viên bán hàng', 'Tiền lương, hoa hồng, thưởng và các chi phí liên quan đến nhân viên bán hàng.', 'Lương nhân viên kinh doanh, hoa hồng bán máy chủ hoặc thưởng theo doanh số hợp đồng dịch vụ.'),
    ('6412', 'Chi phí', 'Chi phí vật liệu và bao bì bán hàng', 'Chi phí vật liệu, bao bì và vật tư sử dụng để đóng gói, bảo quản và giao hàng.', 'Thùng carton, vật liệu chống sốc, màng bọc, pallet, tem nhãn và bao bì dùng để giao thiết bị điện tử.'),
    ('6413', 'Chi phí', 'Chi phí công cụ, dụng cụ bán hàng', 'Chi phí công cụ và thiết bị phục vụ hoạt động bán hàng, trình diễn sản phẩm hoặc tiếp thị.', 'Laptop demo, màn hình trình diễn, máy chiếu, bộ thiết bị mẫu hoặc thiết bị phục vụ hội thảo khách hàng.'),
    ('6414', 'Chi phí', 'Chi phí khấu hao tài sản bán hàng', 'Khấu hao tài sản cố định được sử dụng cho hoạt động bán hàng và giới thiệu sản phẩm.', 'Khấu hao xe giao hàng, hệ thống demo, thiết bị trưng bày hoặc máy tính của bộ phận kinh doanh.'),
    ('6415', 'Chi phí', 'Chi phí bảo hành sản phẩm', 'Chi phí thực tế hoặc chi phí dự phòng liên quan đến nghĩa vụ bảo hành sản phẩm, thiết bị đã bán.', 'Chi phí thay ổ cứng, nguồn điện, module mạng hoặc chi phí kỹ sư xử lý sự cố thiết bị trong thời gian bảo hành.'),
    ('6417', 'Chi phí', 'Chi phí dịch vụ bán hàng thuê ngoài', 'Chi phí mua dịch vụ bên ngoài phục vụ bán hàng, quảng bá, vận chuyển hoặc tiếp cận khách hàng.', 'Chi phí thuê agency marketing, thuê gian hàng triển lãm, quảng cáo trực tuyến, logistics hoặc vận chuyển thiết bị.'),
    ('6418', 'Chi phí', 'Chi phí bán hàng khác', 'Các chi phí bán hàng chưa được phân loại vào các nhóm trên.', 'Chi phí tiếp khách, công tác phí của nhân viên kinh doanh, khảo sát trước bán hàng hoặc hỗ trợ demo tại khách hàng.'),
    ('642', 'Chi phí', 'Chi phí quản lý doanh nghiệp', 'Chi phí phục vụ việc quản lý, điều hành và duy trì hoạt động chung của doanh nghiệp.', 'Lương quản lý, kế toán, nhân sự, chi phí văn phòng, phần mềm nội bộ, pháp lý, kiểm toán và tư vấn.'),
    ('6421', 'Chi phí', 'Chi phí nhân viên quản lý', 'Tiền lương và các khoản liên quan của nhân viên quản lý, hành chính và hỗ trợ doanh nghiệp.', 'Lương giám đốc, kế toán, nhân sự, hành chính, quản lý dự án và nhân viên điều phối dịch vụ.'),
    ('6422', 'Chi phí', 'Chi phí vật liệu quản lý', 'Chi phí vật liệu tiêu hao sử dụng trong hoạt động quản lý và vận hành văn phòng.', 'Nước uống, vật tư vệ sinh, nhiên liệu, giấy và vật tư sử dụng chung tại văn phòng.'),
    ('6423', 'Chi phí', 'Chi phí công cụ, dụng cụ văn phòng', 'Chi phí văn phòng phẩm, công cụ và thiết bị có giá trị nhỏ sử dụng cho hoạt động quản lý.', 'Laptop giá trị nhỏ, màn hình, máy in, điện thoại, router văn phòng, bàn ghế hoặc mực in.'),
    ('6424', 'Chi phí', 'Chi phí khấu hao tài sản cố định quản lý', 'Khấu hao tài sản cố định sử dụng cho hoạt động quản lý doanh nghiệp.', 'Khấu hao máy tính văn phòng, máy chủ nội bộ, xe ô tô, hệ thống camera, bàn ghế và thiết bị văn phòng.'),
    ('6425', 'Chi phí', 'Thuế, phí và lệ phí quản lý', 'Thuế, phí và lệ phí phát sinh trong hoạt động quản lý và điều hành doanh nghiệp.', 'Lệ phí môn bài, phí đăng ký kinh doanh, phí chữ ký số hoặc các khoản phí hành chính không được hoàn lại.'),
    ('6426', 'Chi phí', 'Chi phí dự phòng', 'Chi phí dự phòng cho các khoản tổn thất, nghĩa vụ hoặc rủi ro dự kiến.', 'Dự phòng công nợ khó thu của khách hàng, dự phòng giảm giá thiết bị tồn kho hoặc linh kiện lỗi thời.'),
    ('6427', 'Chi phí', 'Chi phí dịch vụ quản lý thuê ngoài', 'Chi phí mua dịch vụ bên ngoài phục vụ hoạt động quản lý và vận hành doanh nghiệp.', 'Chi phí thuê văn phòng, internet, điện, kiểm toán, tư vấn pháp lý, phần mềm SaaS, cloud và dịch vụ kế toán.'),
    ('6428', 'Chi phí', 'Chi phí quản lý khác', 'Các chi phí quản lý doanh nghiệp khác chưa được phân loại vào các nhóm trên.', 'Công tác phí quản lý, phí ngân hàng, chi phí họp nội bộ, đào tạo nhân viên hoặc chi phí hành chính khác.'),
    ('811', 'Chi phí', 'Chi phí khác', 'Các khoản chi phí phát sinh ngoài hoạt động kinh doanh và tài chính thông thường của doanh nghiệp.', 'Lỗ thanh lý máy chủ cũ, tiền phạt do vi phạm tiến độ hợp đồng, bồi thường sự cố dịch vụ hoặc xóa bỏ thiết bị hư hỏng.'),
    ('821', 'Chi phí', 'Chi phí thuế thu nhập doanh nghiệp', 'Thuế thu nhập doanh nghiệp hiện hành và thuế thu nhập doanh nghiệp hoãn lại được ghi nhận trong kỳ.', 'Thuế thu nhập doanh nghiệp tính trên lợi nhuận chịu thuế từ hoạt động bán thiết bị và cung cấp dịch vụ CNTT.'),
    ('511', 'Doanh thu', 'Doanh thu bán hàng và cung cấp dịch vụ', 'Tổng doanh thu phát sinh từ các hoạt động kinh doanh chính của doanh nghiệp.', 'Doanh thu từ bán máy chủ, thiết bị mạng, phần mềm, triển khai hệ thống, bảo trì, vận hành và hỗ trợ kỹ thuật.'),
    ('5111', 'Doanh thu', 'Doanh thu bán hàng hóa', 'Doanh thu từ hàng hóa do doanh nghiệp mua vào và bán lại mà không thực hiện sản xuất thêm.', 'Bán máy chủ, thiết bị lưu trữ, switch, firewall, laptop, linh kiện hoặc giấy phép phần mềm của hãng thứ ba.'),
    ('5112', 'Doanh thu', 'Doanh thu bán thành phẩm', 'Doanh thu từ sản phẩm do doanh nghiệp sản xuất, lắp ráp, tích hợp hoặc hoàn thiện trước khi bán.', 'Bán bộ appliance, tủ rack tích hợp sẵn hoặc giải pháp phần cứng được công ty lắp ráp và cấu hình trước khi giao khách hàng.'),
    ('5113', 'Doanh thu', 'Doanh thu cung cấp dịch vụ', 'Doanh thu từ việc cung cấp dịch vụ cho khách hàng theo hợp đồng hoặc đơn đặt hàng.', 'Dịch vụ triển khai hệ thống, migration dữ liệu, cấu hình phần mềm, bảo trì, vận hành, hỗ trợ kỹ thuật hoặc thuê bao SaaS.'),
    ('5114', 'Doanh thu', 'Doanh thu được trợ cấp, trợ giá', 'Doanh thu phát sinh từ hàng hóa hoặc dịch vụ được Nhà nước hoặc tổ chức khác trợ cấp, trợ giá.', 'Khoản hỗ trợ để triển khai hạ tầng số, cung cấp dịch vụ CNTT công ích hoặc thực hiện chương trình chuyển đổi số.'),
    ('5117', 'Doanh thu', 'Doanh thu kinh doanh bất động sản đầu tư', 'Doanh thu từ việc bán, cho thuê hoặc khai thác bất động sản được nắm giữ cho mục đích đầu tư.', 'Doanh thu cho thuê văn phòng, kho chứa thiết bị hoặc bất động sản thuộc danh mục đầu tư của công ty.'),
    ('5118', 'Doanh thu', 'Doanh thu hoạt động kinh doanh khác', 'Doanh thu từ hoạt động kinh doanh chính nhưng chưa được phân loại vào các nhóm doanh thu cụ thể khác.', 'Doanh thu đào tạo kỹ thuật, cho thuê thiết bị demo, dịch vụ giám sát từ xa hoặc cho thuê hạ tầng CNTT.'),
    ('515', 'Doanh thu', 'Doanh thu hoạt động tài chính', 'Thu nhập phát sinh từ tiền gửi, đầu tư, ngoại tệ và các hoạt động tài chính của doanh nghiệp.', 'Lãi tiền gửi ngân hàng, lãi chứng chỉ tiền gửi, lãi trái phiếu, cổ tức được chia hoặc lãi chênh lệch tỷ giá.'),
    ('521', 'Giảm trừ doanh thu', 'Các khoản giảm trừ doanh thu', 'Tổng các khoản làm giảm doanh thu bán hàng và cung cấp dịch vụ để xác định doanh thu thuần.', 'Chiết khấu thương mại, thiết bị bị khách hàng trả lại hoặc giảm giá do dịch vụ không đáp ứng đầy đủ cam kết.'),
    ('5211', 'Giảm trừ doanh thu', 'Chiết khấu thương mại', 'Khoản giảm giá dành cho khách hàng khi đáp ứng điều kiện về số lượng, doanh số hoặc điều khoản thương mại.', 'Chiết khấu cho khách hàng mua số lượng lớn máy chủ hoặc ký hợp đồng hỗ trợ kỹ thuật nhiều năm.'),
    ('5212', 'Giảm trừ doanh thu', 'Hàng bán bị trả lại', 'Giá trị hàng hóa hoặc sản phẩm đã bán nhưng bị khách hàng trả lại.', 'Khách hàng trả lại máy chủ hoặc linh kiện do giao sai cấu hình, sai part number hoặc thiết bị bị lỗi.'),
    ('5213', 'Giảm trừ doanh thu', 'Giảm giá hàng bán', 'Khoản giảm giá sau khi bán do sản phẩm, thiết bị hoặc dịch vụ không đáp ứng đầy đủ chất lượng hoặc điều kiện hợp đồng.', 'Giảm giá do thiết bị bị trầy xước, giao hàng chậm, thiếu một phần tính năng hoặc chất lượng dịch vụ thấp hơn cam kết.'),
    ('711', 'Thu nhập khác', 'Thu nhập khác', 'Thu nhập phát sinh ngoài hoạt động kinh doanh chính và hoạt động tài chính thông thường của doanh nghiệp.', 'Lãi thanh lý máy chủ hoặc thiết bị mạng cũ, tiền bồi thường từ nhà cung cấp, tiền phạt hợp đồng thu từ đối tác hoặc thu hồi khoản nợ đã xóa.');

COMMIT;



